function rememberDocument(id,doc){if(doc)docHandles.set(id,{token:doc.token,key:doc.key,name:doc.name,writable:doc.writable});else docHandles.delete(id);if(desktop)try{localStorage.setItem('famtree-documents',JSON.stringify(Object.fromEntries(docHandles)));}catch{}}
