function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,5000)}
function initials(p){return p.name.trim().split(/\s+/).slice(0,2).map(s=>Array.from(s)[0]||'').join('').toUpperCase()}
function dates(p){return [p.birth,p.death].filter(Boolean).join(' – ')||'Fechas sin registrar'}
function avatar(p,large=false){const el=make('span','avatar'+(large?' portrait':''));if(p.portrait){const img=make('img');img.src=p.portrait;img.alt='';el.append(img);}else el.textContent=initials(p);return el;}
