function downloadBytes(bytes,filename,type){const url=URL.createObjectURL(new Blob([bytes],{type}));const a=make('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function download(d,filename){downloadBytes(JSON.stringify(d,null,2)+'\n',filename,'application/json');}
function filename(){return (data().title.replace(/[\\/:*?"<>|]/g,'_').trim()||'FamTree')+'.ftree';}
function remember(id){try{if(id)localStorage.setItem('famtree-active',id);else localStorage.removeItem('famtree-active');}catch{}}
function status(s){$('sync').textContent=s;$('sync').title=s;}
function persist(){
 if(!activeId||!localData)return;const id=activeId,snapshot=localData,serial=++saveSerial;dirty=true;storageError=false;status('Guardando…');
 saveQueue=saveQueue.then(async()=>{try{const rev=await saveProject(id,snapshot,revision.get(id)??null);revision.set(id,rev);if(activeId===id&&serial===saveSerial){dirty=false;storageError=false;if(mode==='local')status('Guardado en este dispositivo');}}catch(e){if(activeId===id&&serial===saveSerial){dirty=true;storageError=true;if(mode==='local')status('No guardado: '+e.message);toast('No se pudo guardar. Exporta una copia .ftree. '+e.message);}}});
}
function setMode(next,automatic=false){
 if(next==='local'&&!localData)return;
 document.body.classList.remove('home-screen');$('startScreen').hidden=true;chosen.clear();mode=next;chartMode='organic';chartRoot=null;$('chartMode').value='organic';document.documentElement.classList.remove('chart-mode-active');$('familyPanel').hidden=true;$('familyMenu').setAttribute('aria-expanded','false');welcomeDismissed=false;selected=null;inspectorOpen=false;$('query').value='';$('scope').value='all';view='tree';$('searchPanel').hidden=true;$('searchToggle').setAttribute('aria-expanded','false');$('sideMenu').hidden=true;$('menuToggle').setAttribute('aria-expanded','false');remember(next==='local'?activeId:null);render(true);status(next==='local'?(storageError?'No guardado: exporta una copia':dirty?'Guardando…':'Guardado en este dispositivo'):'Ejemplo ficticio · solo lectura');
}
function commit(next){if(mode!=='local')return;const validated=project(next);history.push(localData);if(history.length>20)history.shift();future=[];localData=validated;if(!person(selected))selected=null;persist();render(false);}
function undo(){if(mode!=='local'||!history.length)return;future.push(localData);localData=history.pop();if(!person(selected))selected=null;persist();render(false);}
function redo(){if(mode!=='local'||!future.length)return;history.push(localData);localData=future.pop();if(!person(selected))selected=null;persist();render(false);}
async function canSwitch(){await saveQueue;return !dirty||confirm('Hay cambios que no se guardaron. Exporta una copia antes de continuar. ¿Cambiar de proyecto de todos modos?');}
async function activate(id,d,rev=null,create=false){activeId=id;rememberRecent(id);localData=project(d);revision.set(id,rev);history=[];future=[];dirty=false;storageError=false;setMode('local');if(create)persist();}
async function createProject(d,doc=null){if(!await canSwitch())return false;const id=uid();if(doc)rememberDocument(id,doc);await activate(id,d,null,true);await saveQueue;$('projectDialog').close();return true;}
async function showProjects(){if(!$('projectDialog').open)$('projectDialog').showModal();$('projectError').textContent='';const box=$('projectList');box.replaceChildren(make('p','muted','Cargando proyectos…'));await saveQueue;try{const rows=await listProjects();box.replaceChildren();if(!rows.length)box.append(make('p','muted','Todavía no hay proyectos guardados.'));for(const item of rows){const line=make('div','project-row'),b=make('button','result'),t=make('span');b.type='button';t.append(make('strong','',item.title),make('small','',item.count+' personas · '+new Date(item.updated).toLocaleDateString('es-MX')));b.append(t,icon('chevron'));b.addEventListener('click',async()=>{try{if(!await canSwitch())return;const row=await loadProject(item.id);await activate(row.id,row.data,row.revision);$('projectDialog').close();}catch(e){$('projectError').textContent=e.message;}});line.append(b,button('Renombrar '+item.title,'edit',()=>{renameItem=item;$('renameForm').elements.namedItem('title').value=item.title;$('renameError').textContent='';$('renameDialog').showModal();},'small-tool'),button('Duplicar '+item.title,'copy',async()=>{try{if(!await canSwitch())return;const row=await loadProject(item.id);await activate(uid(),{...row.data,title:(row.title+' (copia)').slice(0,120)},null,true);await saveQueue;$('projectDialog').close();}catch(e){$('projectError').textContent=e.message;}}),button('Eliminar '+item.title,'trash',async()=>{if(!confirm('¿Eliminar el proyecto local '+item.title+'? Esta acción no borra las copias descargadas.'))return;try{await saveQueue;await deleteProject(item.id,item.id===activeId?revision.get(item.id):item.revision);rememberDocument(item.id,null);if(item.id===activeId){activeId=null;localData=null;dirty=false;storageError=false;history=[];future=[];setMode('demo');}await showProjects();}catch(e){$('projectError').textContent=e.message;}}));box.append(line);}}catch(e){box.replaceChildren();$('projectError').textContent='No se pudo acceder al almacenamiento local: '+e.message+'. Puedes editar y exportar .ftree, pero no guardar en el navegador.';}}
$('newProjectForm').addEventListener('submit',async e=>{e.preventDefault();const name=new FormData(e.currentTarget).get('title').trim();if(!name)return;await createProject({...blank(),title:name});$('newProjectForm').reset();});
$('copyCurrent').addEventListener('click',async()=>{const source=data();await createProject({...source,title:(source.title+' (copia)').slice(0,120)});});
$('closeProjects').addEventListener('click',()=>$('projectDialog').close());
