$('renameForm').addEventListener('submit',async e=>{e.preventDefault();const name=new FormData(e.currentTarget).get('title').trim(),item=renameItem;if(!item||!name)return;try{await saveQueue;if(item.id===activeId&&mode==='local'){commit({...localData,title:name});await saveQueue;if(dirty)throw Error('No se guardó el nombre.');}else{const row=await loadProject(item.id),d=project({...row.data,title:name}),rev=await saveProject(item.id,d,row.revision);if(item.id===activeId&&!dirty){localData=d;revision.set(item.id,rev);}}$('renameDialog').close();await showProjects();}catch(e){$('renameError').textContent=e.message;}});
