async function openDocument(doc){try{const bytes=new Uint8Array(doc.bytes);if(bytes.length>MAX_FILE_BYTES)throw Error('Archivo demasiado grande.');if(isProtected(bytes)){const next=await finishUI.decrypt(bytes);if(next&&await createProject(next))toast('Archivo protegido abierto como copia local sin cifrado.');return;}const binary=/\.(famtree|ftree)$/i.test(doc.name)||(bytes[0]===70&&bytes[1]===84);const next=binary?decodeFTree(bytes):project(JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes)));if(desktop&&doc.key){const existing=[...docHandles].find(([,d])=>d.key===doc.key);if(existing){if(!await canSwitch())return;try{const row=await loadProject(existing[0]);const local=encodeFTree(row.data),disk=encodeFTree(next);const equal=local.length===disk.length&&local.every((b,i)=>b===disk[i]);if(equal){rememberDocument(row.id,doc);await activate(row.id,row.data,row.revision);$('projectDialog').close();toast('Archivo abierto: '+doc.name);return;}if(confirm('Ya hay un proyecto local para este archivo con cambios diferentes. ¿Abrir el archivo del disco como otro proyecto, conservando el anterior?')===false){await activate(row.id,row.data,row.revision);$('projectDialog').close();return;}}catch{rememberDocument(existing[0],null);}}}if(await createProject(next,desktop&&doc.token?doc:null))toast('Archivo abierto: '+doc.name);}catch(err){toast('No se pudo abrir: '+err.message);if($('projectDialog').open)$('projectError').textContent=err.message;}}
