function editCommand(cmd){const target=document.activeElement;if(target?.closest('input,textarea,[contenteditable]')||document.querySelector('dialog[open]')){if(desktop?.editText)desktop.editText(cmd);else document.execCommand(cmd==='selectAll'?'selectAll':cmd);return;}if(cmd==='copy')copyTree();if(cmd==='paste')pasteTree();if(cmd==='selectAll')selectAllTree();if(cmd==='duplicate')pasteTree(true);}
const dateEditors=[];
for(const name of ['birth','death']){const old=$('personForm').elements.namedItem(name),label=old.parentElement;label.classList.add('date-field');const parts=make('div','date-parts'),day=make('input'),month=make('select'),year=make('input'),toggle=make('button','date-switch','Fecha aproximada o histórica');toggle.type='button';day.type=year.type='text';day.inputMode=year.inputMode='numeric';day.maxLength=2;year.maxLength=4;day.placeholder='Día';year.placeholder='Año';day.id=name+'-day';month.id=name+'-month';year.id=name+'-year';for(const [i,n] of ['Mes','Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'].entries()){const o=make('option','',n);o.value=i?String(i).padStart(2,'0'):'';month.append(o);}day.setAttribute('aria-label',name==='birth'?'Día de nacimiento':'Día de fallecimiento');month.setAttribute('aria-label',name==='birth'?'Mes de nacimiento':'Mes de fallecimiento');year.setAttribute('aria-label',name==='birth'?'Año de nacimiento':'Año de fallecimiento');parts.append(day,month,year);label.append(parts,toggle);const editor={old,parts,day,month,year,toggle,historical:false};dateEditors.push(editor);toggle.addEventListener('click',()=>{if(!editor.historical){try{old.value=dateValue(day.value,month.value,year.value);}catch{}editor.historical=true;}else{const p=dateParts(old.value);day.value=p.day;month.value=p.month;year.value=p.year;editor.historical=false;}paintDate(editor);});}
function paintDate(e){e.old.hidden=!e.historical;e.parts.hidden=e.historical;e.toggle.textContent=e.historical?'Usar día, mes y año':'Fecha aproximada o histórica';syncChoices();}
function resetDateFields(){for(const e of dateEditors){const p=dateParts(e.old.value);e.day.value=p.day;e.month.value=p.month;e.year.value=p.year;e.historical=p.historical;paintDate(e);}}
function saveDateFields(){for(const e of dateEditors)if(!e.historical)e.old.value=dateValue(e.day.value,e.month.value,e.year.value);}

for(const id of ['chartMode','chartRoot','chartDepth','directoryFilter','scope','birth-month','death-month'])enhanceChoice($(id));for(const s of $('relationForm').querySelectorAll('select'))enhanceChoice(s);
function applyWebColors(){const r=document.documentElement;r.style.setProperty('--leaf',$('webLeaf').value);r.style.setProperty('--brown',$('webBranch').value);try{localStorage.setItem('famtree-web-colors',JSON.stringify({leaf:$('webLeaf').value,branch:$('webBranch').value}));}catch{}}try{const c=JSON.parse(localStorage.getItem('famtree-web-colors')||'{}');for(const [id,k] of [['webLeaf','leaf'],['webBranch','branch']])if(/^#[0-9a-f]{6}$/i.test(c[k]||''))$(id).value=c[k];}catch{}applyWebColors();$('webColors').addEventListener('click',()=>$('webColorsDialog').showModal());$('closeWebColors').addEventListener('click',()=>$('webColorsDialog').close());for(const id of ['webLeaf','webBranch'])$(id).addEventListener('input',applyWebColors);$('resetWebColors').addEventListener('click',()=>{$('webLeaf').value='#4a925b';$('webBranch').value='#795139';applyWebColors();});
const researchUI=createResearchUI({data,editable:()=>mode==='local',commit,uid,selectPerson,createProject,downloadBytes,toast,desktop});$('researchOpen').addEventListener('click',()=>researchUI.open('documents'));$('advancedOpen').addEventListener('click',()=>researchUI.open('search'));$('exchangeOpen').addEventListener('click',()=>researchUI.open('exchange'));
const analysis=createAnalysisUI({data,selected:()=>selected,isEditable:()=>mode==='local',commit,selectPerson,listProjects,loadProject,toast});$('analysisTools').addEventListener('click',()=>analysis.open());for(const [id,tab] of [['reviewDuplicates','duplicates'],['reviewCompare','compare'],['reviewKinship','kinship'],['reviewStats','stats']])$(id).addEventListener('click',()=>analysis.open(tab));$('chartMode').addEventListener('change',()=>{chartMode=$('chartMode').value;if(chartMode!=='organic')chartRoot=chooseChartRoot(data(),person(selected)?selected:chartRoot,chartMode);render(true);});$('chartRoot').addEventListener('change',()=>{chartRoot=$('chartRoot').value;renderTree(false);});$('chartDepth').addEventListener('change',()=>renderTree(false));$('chartUseSelected').addEventListener('click',()=>{if(person(selected)){chartRoot=selected;renderTree(false);}});
const dossier=createDossier({getPerson:person,uid,savePerson:p=>{if(mode!=='local')throw Error('Abre un proyecto editable.');commit({...data(),people:data().people.map(x=>x.id===p.id?p:x)});toast('Expediente guardado.');},saveRelation:(old,next)=>{if(mode!=='local')throw Error('Abre un proyecto editable.');commit({...data(),relations:data().relations.map(r=>r.type===old.type&&r.from===old.from&&r.to===old.to?next:r)});toast('Vínculo guardado.');}});$('relationForm').elements.namedItem('type').addEventListener('change',()=>{$('newRelationKind').hidden=$('relationForm').elements.namedItem('type').value==='partner';});
init().then(()=>{if(desktop){$('projectDescription').textContent='Los proyectos locales se guardan en esta instalación. Guardar escribe un archivo .ftree en tu Mac; Guardar como crea otra copia.';let incoming=Promise.resolve();desktop.onDocument(doc=>{incoming=incoming.then(()=>openDocument(doc));});desktop.onCommand(cmd=>{if(cmd==='new')newTree();else if(cmd==='open')openFile();else if(cmd==='save')saveFile();else if(cmd==='saveAs')saveFile(true);else if(cmd==='fit')fitTree();else if(cmd==='search'&&$('searchPanel').hidden)$('searchToggle').click();});desktop.ready();}});
